cat > zz_heldout_test.go <<'EOF'
package shop

import "testing"

func TestHeldoutApplyCouponsLargestOnly(t *testing.T) {
	for _, c := range []struct {
		total    int
		percents []int
		want     int
	}{
		{1000, []int{10, 20}, 800},
		{1000, []int{20, 10}, 800},
		{1000, nil, 1000},
		{999, []int{50}, 500},
	} {
		if got := ApplyCoupons(c.total, c.percents); got != c.want {
			t.Errorf("ApplyCoupons(%d, %v) = %d, want %d", c.total, c.percents, got, c.want)
		}
	}
}
EOF
go test -count=1 -run Heldout ./...; rc=$?; rm -f zz_heldout_test.go; exit $rc
